BW = 1.55e12      # assumed achievable A100-80GB HBM bandwidth B/s (spec 2.04e12)
FP16_TF = 187e12  # assumed achievable FP16 tensor TFLOPs (spec 312e12, ~60%)
INT4_TF = 400e12  # assumed achievable INT4 GEMM (spec peak 1248e12, ~32% eff.)
BITS_W4 = 4.25*1.0  # 4-bit + fp16 group scales (g=128 -> +0.25 bit/param)
def G(x): return x/1e9
models = {
 "7B":  dict(L=32, d=4096, h=32, kvh=32, hd=128, f=11008, V=32000),
 "13B": dict(L=40, d=5120, h=40, kvh=40, hd=128, f=13824, V=32000),
}
for name,m in models.items():
    L,d,kvh,hd,f,V = m["L"],m["d"],m["kvh"],m["hd"],m["f"],m["V"]
    w_lin = L*(4*d*d + 3*d*f)          # attn(q,k,v,o) + ffn(gate,up,down)
    lm_head = d*V
    Wtot = w_lin + lm_head             # bytes-eligible per decoded token (b=1)
    kv_per_pos = L*kvh*hd*2            # K+V elements per position
    print(f"--- LLaMa-2-{name} ---")
    print(f"linear+lm_head params: {G(Wtot):.2f} B")
    for S in (512,1024,2048):
        fp = 2*Wtot + 2*kv_per_pos*(S+64)          # mid-decode avg ctx ~S+64
        q4 = (BITS_W4/8)*Wtot + (BITS_W4/8)*kv_per_pos*(S+64)
        print(f" S~{S+64:5d} tok: FP16 {G(fp):7.2f} GB/tok -> {fp/BW*1e3:6.2f} ms/tok ({BW/fp:5.0f} t/s) | "
              f"W4A4KV4 {G(q4):6.2f} GB/tok -> {q4/BW*1e3:5.2f} ms/tok ({BW/q4:5.0f} t/s) | ratio {fp/q4:4.2f}x")
    # prefill compute-bound estimate (b=1)
    for S in (512,1024,2048):
        fl = 2*Wtot*S
        t16 = fl/FP16_TF; t4 = fl/INT4_TF
        print(f" prefill S={S}: flops {fl/1e12:.2f} TF | FP16 {t16*1e3:7.1f} ms ({S/t16/1000:6.1f} kt/s) | INT4 {t4*1e3:6.1f} ms ({S/t4/1000:6.1f} kt/s) | ratio {t16/t4:4.2f}x")
